// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {AirDropContract} from "../src/AirDropContract.sol";

contract InvMutTest is Test {
    AirDropContract c;
    function setUp() public { c = new AirDropContract(); }
    function testFuzz_property(address[] memory tos, uint[] memory vs) public {
        vm.assume(tos.length > 0);
        vm.assume(vs.length > 0);
        vm.assume(tos.length == vs.length);
        address contract_address = address(0);
        bool ok;
        try c.transfer(contract_address, tos, vs) returns (bool) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}
